    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != 4:
                points.setdefault(color, []).append((r, c))

    ones = points.get(1, [])
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            r, c = r1, c1
            while True:
                if out[r][c] == 4:
                    out[r][c] = 1
                if (r, c) == (r2, c2):
                    break
                r += sr
                c += sc
            # A different-colored point on the 1 segment gets a line
            # in the perpendicular diagonal direction.
            for color, coords in points.items():
                if color == 1:
                    continue
                for pr, pc in coords:
                    if (pr-r1) * dc == (pc-c1) * dr and min(r1, r2) <= pr <= max(r1, r2) and min(c1, c2) <= pc <= max(c1, c2):
